function u(n){return`사용자 #${n.user_id}`}function i(n){let e=(n.name??"").trim();return e===""?u(n):e}function s(n,e){let t=i(n);return e.some(r=>r.user_id!==n.user_id&&i(r)===t)}function o(n,e){let t=i(n);if(!s(n,e))return t;let r=(n.github_login??"").trim();return r===""?`${t} · 구분 미등록`:`${t} · @${r}`}function f(n,e){if(!s(n,e))return!0;let t=o(n,e);return!e.some(r=>r.user_id!==n.user_id&&o(r,e)===t)}function a(){return"이름이 같은 팀원이 있습니다 — 내 정보에서 이름에 별칭(예: 김민수A)을 붙여 구분해 주세요"}export{o as a,f as b,a as c};
